BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "dm_dicionario_questoes_ceticbr" (
	"id_dicionario"	INTEGER,
	"cd_questao_ceticbr"	TEXT,
	"ds_questao_ceticbr"	TEXT,
	"nm_questao_variavel"	TEXT,
	"nm_curto_variavel"	TEXT
);
CREATE TABLE IF NOT EXISTS "dm_mercado_atuacao" (
	"id_merc_atuacao"	text(4) NOT NULL,
	"ds_merc_atuacao"	text(256) DEFAULT NULL,
	"cod_ibge"	text(1) DEFAULT NULL,
	"ds_merc_atuacao_abrev"	TEXT(32),
	PRIMARY KEY("id_merc_atuacao")
);
CREATE TABLE IF NOT EXISTS "dm_porte_empresa" (
	"id_porte_empresa"	text(4) NOT NULL,
	"ds_porte_empresa"	text(32) NOT NULL,
	PRIMARY KEY("id_porte_empresa")
);
CREATE TABLE IF NOT EXISTS "dm_resposta_sn" (
	"id_resposta_sn"	INTEGER NOT NULL,
	"ds_resposta_sn"	text(16) NOT NULL,
	PRIMARY KEY("id_resposta_sn")
);
CREATE TABLE IF NOT EXISTS "dm_resumo_pesquisa" (
	"ano_pesquisa"	text(8) NOT NULL,
	"amostra_planejada"	INTEGER DEFAULT NULL,
	"empresas_respondentes"	INTEGER NOT NULL,
	"link_publicacao"	text(1024),
	"estimativa_empresas"	INTEGER,
	PRIMARY KEY("ano_pesquisa")
);
CREATE TABLE IF NOT EXISTS "ft_ceticbr_mercado" (
	"id_mercado"	INTEGER NOT NULL,
	"ano_pesquisa"	text(8) NOT NULL,
	"cd_variavel"	text(8) NOT NULL,
	"id_dm_mercado"	text(4) NOT NULL,
	"qtd_resposta_sim"	INTEGER DEFAULT NULL,
	PRIMARY KEY("id_mercado" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_ceticbr_porte" (
	"id_porte"	INTEGER NOT NULL,
	"ano_pesquisa"	text(8) NOT NULL,
	"cd_variavel"	text(8) NOT NULL,
	"id_dm_porte"	text(4) NOT NULL,
	"qtd_resposta_sim"	INTEGER DEFAULT NULL,
	PRIMARY KEY("id_porte" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_ceticbr_totais" (
	"id_totais"	INTEGER NOT NULL,
	"ano_pesquisa"	text(8) NOT NULL,
	"cd_variavel"	text(8) NOT NULL,
	"contexto"	text(64) NOT NULL,
	"qtd_resposta_sim"	INTEGER DEFAULT NULL,
	PRIMARY KEY("id_totais" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_cma_3DesafiosGMO" (
	"id_3DesafiosGMO"	INTEGER NOT NULL,
	"ds_3DesafiosGMO"	varchar(128),
	PRIMARY KEY("id_3DesafiosGMO" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_cma_engajamentoTipico" (
	"id_engajamentoTipico"	INTEGER NOT NULL,
	"ds_engajamentotipico"	varchar(128),
	PRIMARY KEY("id_engajamentoTipico" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_cma_maiorDesafioTD" (
	"id_maiorDesafioTD"	INTEGER NOT NULL,
	"ds_maiordesafioTD"	varchar(128),
	PRIMARY KEY("id_maiorDesafioTD" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_cma_principal" (
	"id_principal"	INTEGER NOT NULL,
	"id_original"	INTEGER DEFAULT NULL,
	"mercado_atuacao"	varchar(64),
	"porte_empresa"	varchar(64),
	"tem_cmo"	varchar(16),
	"area_vinculo"	varchar(64),
	"consistencia_engajamento"	varchar(128),
	"maturidade_praticas"	varchar(128),
	"projetos_com_gmo"	varchar(16),
	"maturidade_gmo_pais"	varchar(32),
	PRIMARY KEY("id_principal" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ft_cma_tipoMudanca" (
	"id_tipomudanca"	INTEGER NOT NULL,
	"ds_tipomudanca"	varchar(128),
	PRIMARY KEY("id_tipomudanca" AUTOINCREMENT)
);
